import type { Metadata } from "next";
import Link from "next/link";
import { requireAdmin } from "@/lib/admin-guard";
import { RANGE_DAYS, getStats, rangeFrom, type RangeDays } from "@/lib/analytics";
import { getGaSummary } from "@/lib/ga-data";
import { serviceAccountError } from "@/lib/google-auth";
import { proxyUsageToday } from "@/lib/proxy-budget";
import { routingReport } from "@/lib/proxy-routing";
import AdminBar from "./AdminBar";
import AdsEditor from "@/components/admin/AdsEditor";

export const metadata: Metadata = {
  title: "Admin dashboard",
  robots: { index: false, follow: false },
};

// Always render fresh; never cache the dashboard.
export const dynamic = "force-dynamic";

function pct(n: number): string {
  return `${Math.round(n * 100)}%`;
}

/** "last 24 hours" or "last 7 days", for headings and empty states. */
function periodLabel(days: RangeDays): string {
  return days === 1 ? "last 24 hours" : `last ${days} days`;
}

/** How a count moved against the period of the same length before it. */
function changeNote(now: number, before: number, days: RangeDays): string {
  const prior = days === 1 ? "the day before" : `the ${days} days before`;
  if (before === 0) return now === 0 ? `none in ${prior} either` : `none in ${prior}`;
  const change = Math.round(((now - before) / before) * 100);
  if (change === 0) return `same as ${prior}`;
  return `${change > 0 ? "up" : "down"} ${Math.abs(change)}% on ${prior}`;
}

/** A chart bar's caption: the hour (UTC) for a day, the date otherwise. */
function barLabel(start: number, end: number, days: RangeDays): string {
  return days === 1
    ? new Date(start).toISOString().slice(11, 13)
    : new Date(end - 1).toISOString().slice(5, 10);
}

/**
 * The period switch. Plain links, so the choice lives in the address
 * (/admin?range=28d) and survives Refresh, a reload, or a bookmark.
 */
function RangeSwitch({ current }: { current: RangeDays }) {
  return (
    <nav
      aria-label="Period"
      className="glass glass-hairline inline-flex rounded-xl p-1"
    >
      {RANGE_DAYS.map((d) => (
        <Link
          key={d}
          href={`/admin?range=${d}d`}
          scroll={false}
          aria-current={d === current ? "page" : undefined}
          className={`rounded-lg px-3 py-1.5 text-sm font-medium transition ${
            d === current
              ? "bg-violet-600 text-white"
              : "text-neutral-600 hover:bg-black/5 dark:text-neutral-300 dark:hover:bg-white/10"
          }`}
        >
          {d === 1 ? "1 day" : `${d} days`}
        </Link>
      ))}
    </nav>
  );
}

function StatCard({
  label,
  value,
  sub,
}: {
  label: string;
  value: string | number;
  sub?: string;
}) {
  return (
    <div className="glass glass-hairline rounded-2xl p-5">
      <p className="text-xs font-medium uppercase tracking-wide text-neutral-500 dark:text-neutral-400">
        {label}
      </p>
      <p className="mt-1 text-2xl font-bold text-neutral-900 dark:text-white">
        {value}
      </p>
      {sub && (
        <p className="mt-0.5 text-xs text-neutral-500 dark:text-neutral-400">
          {sub}
        </p>
      )}
    </div>
  );
}

export default async function AdminDashboard({
  searchParams,
}: {
  searchParams: Promise<{ [key: string]: string | string[] | undefined }>;
}) {
  await requireAdmin();
  const range = rangeFrom((await searchParams).range);
  const period = periodLabel(range);
  const stats = await getStats(range);
  const gaId = process.env.NEXT_PUBLIC_GA_ID;
  const ga = await getGaSummary(range);
  const proxyOn = !!process.env.YTDLP_PROXY;
  const proxy = proxyOn ? await proxyUsageToday() : null;
  // What the server has actually learned about reaching each site. This is the
  // number to watch before cancelling the proxy: a site sitting at "direct"
  // is costing nothing today, whatever the host list says.
  const routing = Object.entries(routingReport()).sort((a, b) => a[0].localeCompare(b[0]));

  const maxBar = Math.max(
    1,
    ...stats.series.map((d) => Math.max(d.pageviews, d.downloads)),
  );
  // Captions under every bar crowd a phone screen at 24 or 28 bars.
  const labelEvery = range === 1 ? 6 : range === 28 ? 7 : 1;

  return (
    // w-full matters: the body is a flex column, where a centred <main> sizes
    // itself to its widest content (the 640px ads table) rather than the
    // screen, which zoomed the whole dashboard out on a phone.
    <main className="mx-auto w-full max-w-5xl px-4 py-8">
      <div className="flex items-center justify-between gap-4">
        <div>
          <h1 className="font-display text-2xl font-bold text-neutral-900 dark:text-white">
            Dashboard
          </h1>
          <div className="flex gap-3 text-sm">
            <Link
              href="/admin/seo"
              className="text-violet-600 hover:underline dark:text-violet-400"
            >
              SEO audit
            </Link>
            <Link
              href="/"
              className="text-violet-600 hover:underline dark:text-violet-400"
            >
              View site
            </Link>
          </div>
        </div>
        <AdminBar generatedAt={stats.generatedAt} />
      </div>

      <div className="mt-6 flex flex-wrap items-center gap-x-4 gap-y-2">
        <RangeSwitch current={range} />
        <p className="text-xs text-neutral-500 dark:text-neutral-400">
          Figures below cover the {period}, apart from the routing, proxy and
          recent activity panels, which are always live.
          {stats.dataFrom !== null && stats.dataFrom > stats.since && (
            <>
              {" "}
              Records start on {new Date(stats.dataFrom).toISOString().slice(0, 10)}, so
              this period is not complete.
            </>
          )}
        </p>
      </div>

      <div className="mt-4 grid grid-cols-2 gap-4 lg:grid-cols-4">
        <StatCard
          label="Pageviews"
          value={stats.pageviews.toLocaleString()}
          sub={changeNote(stats.pageviews, stats.previous.pageviews, range)}
        />
        <StatCard
          label="Downloads"
          value={stats.downloads.toLocaleString()}
          sub={changeNote(stats.downloads, stats.previous.downloads, range)}
        />
        <StatCard
          label="Link lookups"
          value={stats.lookups.toLocaleString()}
          sub={`${pct(stats.lookupSuccessRate)} succeeded, ${changeNote(stats.lookups, stats.previous.lookups, range)}`}
        />
        <StatCard
          label="Lookup → download"
          value={pct(stats.conversionRate)}
          sub="conversion rate"
        />
      </div>

      <section className="glass glass-hairline mt-4 rounded-2xl p-5">
        <div className="flex items-center justify-between gap-3">
          <h2 className="font-display text-sm font-semibold text-neutral-900 dark:text-white">
            How each site is being reached
          </h2>
          <span className="text-xs text-neutral-500 dark:text-neutral-400">
            {proxyOn ? "proxy configured" : "no proxy configured"}
          </span>
        </div>
        {routing.length === 0 ? (
          <p className="mt-2 text-sm text-neutral-500 dark:text-neutral-400">
            Nothing learned yet. These verdicts are held in memory, so they start
            empty after a restart and fill in as links are looked up.
          </p>
        ) : (
          <ul className="mt-3 space-y-2">
            {routing.map(([host, v]) => (
              <li key={host} className="flex items-center justify-between text-sm">
                <span className="text-neutral-700 dark:text-neutral-300">{host}</span>
                <span className="flex items-center gap-2">
                  <span
                    className={`rounded px-1.5 py-0.5 text-[11px] font-medium ${
                      v.direct
                        ? "bg-emerald-500/15 text-emerald-700 dark:text-emerald-400"
                        : "bg-amber-500/15 text-amber-700 dark:text-amber-400"
                    }`}
                  >
                    {v.direct ? "direct, free" : proxyOn ? "via paid proxy" : "unavailable"}
                  </span>
                  <span className="text-xs text-neutral-500 dark:text-neutral-400">
                    {v.ageMinutes < 60
                      ? `${v.ageMinutes}m ago`
                      : `${Math.round(v.ageMinutes / 60)}h ago`}
                  </span>
                </span>
              </li>
            ))}
          </ul>
        )}
        <p className="mt-3 text-xs text-neutral-500 dark:text-neutral-400">
          Checked again after 6 hours when a site answers directly, 12 hours after
          a refusal. If every row here says direct, the proxy is being paid for
          and not used.
        </p>
      </section>

      {proxy && (
        <section className="glass glass-hairline mt-4 rounded-2xl p-5">
          <div className="flex items-center justify-between gap-3">
            <h2 className="font-display text-sm font-semibold text-neutral-900 dark:text-white">
              Proxy usage today (YouTube)
            </h2>
            <span
              className={`text-xs font-medium ${
                proxy.capMb > 0 && proxy.usedMb >= proxy.capMb
                  ? "text-red-600 dark:text-red-400"
                  : "text-neutral-500 dark:text-neutral-400"
              }`}
            >
              {proxy.capMb === 0
                ? "no daily cap"
                : proxy.usedMb >= proxy.capMb
                  ? "daily cap reached"
                  : "within budget"}
            </span>
          </div>
          <p className="mt-2 text-sm text-neutral-700 dark:text-neutral-300">
            {proxy.downloads.toLocaleString()} proxied download
            {proxy.downloads === 1 ? "" : "s"} · ~{proxy.usedMb} MB used
            {proxy.capMb > 0 ? ` of ${proxy.capMb} MB` : ""}
          </p>
          {proxy.capMb > 0 && (
            <div className="mt-2 h-1.5 overflow-hidden rounded-full bg-black/10 dark:bg-white/10">
              <div
                className={`h-full rounded-full ${
                  proxy.usedMb >= proxy.capMb ? "bg-red-500" : "bg-violet-600"
                }`}
                style={{ width: `${Math.min(100, Math.round((proxy.usedMb / proxy.capMb) * 100))}%` }}
              />
            </div>
          )}
          <p className="mt-2 text-xs text-neutral-500 dark:text-neutral-400">
            Only YouTube (and other blocked sites) use the paid proxy. Estimated
            from download sizes. Adjust the ceiling with YTDLP_PROXY_DAILY_MB.
          </p>
        </section>
      )}

      <section className="mt-6 glass glass-hairline rounded-2xl p-5">
        <h2 className="text-sm font-semibold text-neutral-900 dark:text-white">
          {range === 1 ? "Last 24 hours, by hour (UTC)" : `Last ${range} days, by day`}
        </h2>
        <div
          className={`mt-4 flex items-end ${range === 7 ? "gap-1.5" : "gap-0.5 sm:gap-1"}`}
          style={{ height: 140 }}
        >
          {stats.series.map((d, i) => (
            <div
              key={d.start}
              className="group flex min-w-0 flex-1 flex-col items-center justify-end gap-1"
              title={`${new Date(d.start).toISOString().slice(0, 16).replace("T", " ")} to ${new Date(d.end).toISOString().slice(0, 16).replace("T", " ")} UTC: ${d.pageviews} views, ${d.downloads} downloads`}
            >
              <div className="flex w-full items-end justify-center gap-px" style={{ height: 110 }}>
                <div
                  className="w-1/2 rounded-t bg-violet-200 dark:bg-violet-900/60"
                  style={{ height: `${(d.pageviews / maxBar) * 100}%` }}
                />
                <div
                  className="w-1/2 rounded-t bg-violet-600"
                  style={{ height: `${(d.downloads / maxBar) * 100}%` }}
                />
              </div>
              <span className="h-3 text-[9px] leading-3 text-neutral-400">
                {(stats.series.length - 1 - i) % labelEvery === 0
                  ? barLabel(d.start, d.end, range)
                  : ""}
              </span>
            </div>
          ))}
        </div>
        <div className="mt-3 flex gap-4 text-xs text-neutral-500 dark:text-neutral-400">
          <span className="flex items-center gap-1.5">
            <span className="h-2.5 w-2.5 rounded-sm bg-violet-200 dark:bg-violet-900/60" />
            Pageviews
          </span>
          <span className="flex items-center gap-1.5">
            <span className="h-2.5 w-2.5 rounded-sm bg-violet-600" />
            Downloads
          </span>
        </div>
      </section>

      <div className="mt-6 grid gap-4 lg:grid-cols-2">
        <section className="glass glass-hairline rounded-2xl p-5">
          <h2 className="text-sm font-semibold text-neutral-900 dark:text-white">
            Top sites looked up
          </h2>
          {stats.topSites.length === 0 ? (
            <p className="mt-3 text-sm text-neutral-500 dark:text-neutral-400">
              No lookups recorded yet.
            </p>
          ) : (
            <ul className="mt-3 space-y-2">
              {stats.topSites.map((s) => (
                <li key={s.site} className="flex items-center justify-between text-sm">
                  <span className="text-neutral-700 dark:text-neutral-300">{s.site}</span>
                  <span className="font-medium text-neutral-900 dark:text-white">
                    {s.count.toLocaleString()}
                  </span>
                </li>
              ))}
            </ul>
          )}
          <div className="mt-4 flex gap-4 border-t border-black/5 pt-3 text-xs text-neutral-500 dark:border-white/10 dark:text-neutral-400">
            <span>Video: {stats.downloadsByMode.video.toLocaleString()}</span>
            <span>Audio (MP3): {stats.downloadsByMode.audio.toLocaleString()}</span>
          </div>
        </section>

        {/*
          What is failing, and where. Successes were always attributed and
          failures never were, so a whole platform could break and show up only
          as a slightly worse success rate.
        */}
        <section className="glass glass-hairline rounded-2xl p-5">
          <h2 className="text-sm font-semibold text-neutral-900 dark:text-white">
            Failing links by site, {period}
          </h2>
          {stats.lookupFailures.length === 0 ? (
            <p className="mt-3 text-sm text-neutral-500 dark:text-neutral-400">
              Nothing has failed in the {period}.
            </p>
          ) : (
            <ul className="mt-3 space-y-2">
              {stats.lookupFailures.map((f) => (
                <li key={f.host} className="flex items-center justify-between text-sm">
                  <span className="text-neutral-700 dark:text-neutral-300">
                    {f.host}
                    <span className="ml-2 rounded bg-neutral-500/15 px-1.5 py-0.5 text-[11px] font-medium text-neutral-600 dark:text-neutral-300">
                      {f.topCode}
                    </span>
                  </span>
                  <span className="font-medium text-neutral-900 dark:text-white">
                    {f.count.toLocaleString()}
                  </span>
                </li>
              ))}
            </ul>
          )}
          <p className="mt-3 text-xs text-neutral-500 dark:text-neutral-400">
            UNSUPPORTED_SITE on a site you support usually means a URL shape
            changed, not that visitors are pasting rubbish. AGE_CHECK_REGION
            means the site holds videos back from visitors in the server&apos;s
            country (France) until they prove their age; only an exit in another
            country changes that.
          </p>
        </section>

        {/*
          Downloads, not lookups, and the share of them that could cost metered
          proxy data. This is the panel to read before deciding whether a
          platform is worth paying to support.
        */}
        <section className="glass glass-hairline rounded-2xl p-5">
          <h2 className="text-sm font-semibold text-neutral-900 dark:text-white">
            Downloads by platform
          </h2>
          {stats.downloadSites.length === 0 ? (
            <p className="mt-3 text-sm text-neutral-500 dark:text-neutral-400">
              No downloads recorded yet. Platform is recorded from the lookup that
              preceded the download, so older events are unlabelled.
            </p>
          ) : (
            <ul className="mt-3 space-y-2">
              {stats.downloadSites.map((s) => {
                const share = stats.downloads
                  ? Math.round((s.count / stats.downloads) * 100)
                  : 0;
                return (
                  <li key={s.site} className="flex items-center justify-between text-sm">
                    <span className="text-neutral-700 dark:text-neutral-300">
                      {s.site}
                      {s.proxied > 0 ? (
                        <span className="ml-2 rounded bg-amber-500/15 px-1.5 py-0.5 text-[11px] font-medium text-amber-700 dark:text-amber-400">
                          {s.proxied.toLocaleString()} metered
                        </span>
                      ) : null}
                    </span>
                    <span className="font-medium text-neutral-900 dark:text-white">
                      {s.count.toLocaleString()}
                      <span className="ml-1.5 text-xs font-normal text-neutral-500 dark:text-neutral-400">
                        {share}%
                      </span>
                    </span>
                  </li>
                );
              })}
            </ul>
          )}
        </section>

        {/*
          The Trustpilot prompt after a browser's first download, and its next
          one if closed. Opened is the review page being opened from it, not a
          review written: whether one was written only shows on Trustpilot.
        */}
        <section className="glass glass-hairline rounded-2xl p-5">
          <h2 className="text-sm font-semibold text-neutral-900 dark:text-white">
            Trustpilot prompt
          </h2>
          <ul className="mt-3 space-y-2">
            {(
              [
                ["Shown", stats.reviewPrompt.shown],
                ["Review page opened", stats.reviewPrompt.opened],
                ["Closed", stats.reviewPrompt.closed],
              ] as const
            ).map(([label, n]) => (
              <li key={label} className="flex items-center justify-between text-sm">
                <span className="text-neutral-700 dark:text-neutral-300">{label}</span>
                <span className="font-medium text-neutral-900 dark:text-white">
                  {n.toLocaleString()}
                </span>
              </li>
            ))}
          </ul>
          <a
            href="https://www.trustpilot.com/review/pasteandsave.com"
            target="_blank"
            rel="noopener noreferrer"
            className="mt-3 inline-block text-xs font-medium text-violet-700 hover:underline dark:text-violet-300"
          >
            See the reviews on Trustpilot
          </a>
        </section>

        <section className="glass glass-hairline rounded-2xl p-5">
          <h2 className="text-sm font-semibold text-neutral-900 dark:text-white">
            Top pages
          </h2>
          {stats.topPages.length === 0 ? (
            <p className="mt-3 text-sm text-neutral-500 dark:text-neutral-400">
              No pageviews recorded yet.
            </p>
          ) : (
            <ul className="mt-3 space-y-2">
              {stats.topPages.map((p) => (
                <li key={p.path} className="flex items-center justify-between gap-3 text-sm">
                  <span className="truncate text-neutral-700 dark:text-neutral-300">
                    {p.path}
                  </span>
                  <span className="font-medium text-neutral-900 dark:text-white">
                    {p.count.toLocaleString()}
                  </span>
                </li>
              ))}
            </ul>
          )}
        </section>
      </div>

      <section className="mt-6 glass glass-hairline rounded-2xl p-5">
        <div className="flex items-center justify-between">
          <h2 className="text-sm font-semibold text-neutral-900 dark:text-white">
            Google Analytics
          </h2>
          {/* GA counts whole days in the property's time zone (see gaDateRange). */}
          <span className="text-xs text-neutral-400">
            {range === 1 ? "today so far" : `last ${range} days, including today`}
          </span>
        </div>

        {ga.status === "ok" ? (
          <>
            <div className="mt-3 grid grid-cols-3 gap-4">
              <div>
                <p className="text-xl font-bold text-neutral-900 dark:text-white">
                  {ga.data.activeUsers.toLocaleString()}
                </p>
                <p className="text-xs text-neutral-500 dark:text-neutral-400">Users</p>
              </div>
              <div>
                <p className="text-xl font-bold text-neutral-900 dark:text-white">
                  {ga.data.pageViews.toLocaleString()}
                </p>
                <p className="text-xs text-neutral-500 dark:text-neutral-400">Pageviews</p>
              </div>
              <div>
                <p className="text-xl font-bold text-neutral-900 dark:text-white">
                  {ga.data.sessions.toLocaleString()}
                </p>
                <p className="text-xs text-neutral-500 dark:text-neutral-400">Sessions</p>
              </div>
            </div>
            <div className="mt-4 grid gap-4 sm:grid-cols-2">
              <div>
                <p className="text-xs font-medium text-neutral-500 dark:text-neutral-400">
                  Top countries
                </p>
                <ul className="mt-1 space-y-1 text-sm">
                  {ga.data.topCountries.map((c) => (
                    <li key={c.name} className="flex justify-between">
                      <span className="text-neutral-700 dark:text-neutral-300">{c.name}</span>
                      <span className="text-neutral-500 dark:text-neutral-400">
                        {c.users.toLocaleString()}
                      </span>
                    </li>
                  ))}
                </ul>
              </div>
              <div>
                <p className="text-xs font-medium text-neutral-500 dark:text-neutral-400">
                  Top pages (GA)
                </p>
                <ul className="mt-1 space-y-1 text-sm">
                  {ga.data.topPages.map((p) => (
                    <li key={p.path} className="flex justify-between gap-3">
                      <span className="truncate text-neutral-700 dark:text-neutral-300">
                        {p.path}
                      </span>
                      <span className="shrink-0 text-neutral-500 dark:text-neutral-400">
                        {p.views.toLocaleString()}
                      </span>
                    </li>
                  ))}
                </ul>
              </div>
            </div>
          </>
        ) : ga.status === "error" ? (
          <p className="mt-2 text-sm text-amber-600 dark:text-amber-400">
            Couldn&apos;t load GA data: {ga.message}. Check GA4_PROPERTY_ID and
            that the service account has Viewer access to the property.
          </p>
        ) : (
          <div className="mt-2 text-sm text-neutral-600 dark:text-neutral-400">
            <p>
              {gaId
                ? "Client tracking is on. To show numbers here, connect the GA Data API:"
                : "Not connected. To pull GA numbers into this dashboard:"}
            </p>
            {/* The specific reason, not just the generic steps. "Not
                configured" covers a missing variable, an unreadable file and a
                key of the wrong type, and guessing which is a slow way to
                spend an evening. */}
            {serviceAccountError() && (
              <p className="mt-2 rounded-lg bg-amber-50 px-3 py-2 text-xs text-amber-700 dark:bg-amber-950/40 dark:text-amber-300">
                {serviceAccountError()}
              </p>
            )}
            <ol className="mt-2 list-decimal space-y-2 pl-5 text-neutral-500 dark:text-neutral-400">
              <li>
                At console.cloud.google.com, create a project, enable the{" "}
                <span className="font-mono">Google Analytics Data API</span>, then
                create a service account and download its JSON key.
              </li>
              <li>
                In GA4 → Admin → Property access management, add the service
                account email (it ends in{" "}
                <span className="font-mono">.iam.gserviceaccount.com</span>) as a
                Viewer.
              </li>
              <li>
                Save the key on the server as{" "}
                <span className="font-mono">/opt/pasteandsave/ga-key.json</span>.
                Nothing else needs setting: the site finds the file there and
                uses property 547077098. The key is a credential, so keep it in
                that file rather than pasting it into a web form.
              </li>
            </ol>
            <p className="mt-2 text-xs text-neutral-400">
              Numbers appear here on the next load once the file is in place.
              Visitor tracking on the site itself is separate and already runs
              from <span className="font-mono">NEXT_PUBLIC_GA_ID</span>.
            </p>
          </div>
        )}
      </section>

      <AdsEditor />

      <section className="mt-6 glass glass-hairline rounded-2xl p-5">
        <h2 className="text-sm font-semibold text-neutral-900 dark:text-white">
          Recent activity
        </h2>
        {stats.recent.length === 0 ? (
          <p className="mt-3 text-sm text-neutral-500 dark:text-neutral-400">
            Nothing yet.
          </p>
        ) : (
          <ul className="mt-3 divide-y divide-black/5 text-sm dark:divide-white/10">
            {stats.recent.map((ev, i) => (
              <li key={i} className="flex items-center justify-between gap-3 py-2">
                <span className="text-neutral-700 dark:text-neutral-300">
                  {ev.type === "pageview" && `Viewed ${ev.path ?? "/"}`}
                  {ev.type === "lookup" &&
                    `Looked up ${ev.site ?? "a link"}${ev.ok === false ? " (failed)" : ""}`}
                  {ev.type === "download" && `Downloaded ${ev.mode === "audio" ? "MP3 audio" : "video"}`}
                  {ev.type === "review" && `Trustpilot prompt ${ev.action ?? ""}`}
                </span>
                <span className="shrink-0 text-xs text-neutral-400">
                  {new Date(ev.t).toLocaleString()}
                </span>
              </li>
            ))}
          </ul>
        )}
      </section>

      <p className="mt-6 text-center text-xs text-neutral-400">
        First-party analytics store no cookies, IPs or personal data.
      </p>
    </main>
  );
}
